import os as _os
import sys as _sys
import io as _io
import json as _json
import re as _re
import fnmatch as _fnmatch

_MATCHER = 'Bash(git push*)'

# Bound the standalone shim read before JSON parsing so a malicious or buggy
# upstream cannot cause unbounded allocation (CWE-400).
_HOOK_STDIN_CEILING_BYTES = 64 * 1024 * 1024

# Apply the normal payload policy only after matcher selection. Multi-call
# events can contain a large unrelated call that must not deny a small matched
# call.
_MATCHED_SHIM_PAYLOAD_LIMIT_BYTES = 2 * 1024 * 1024
_MAX_MATCHER_TOOL_CALLS = 256


def _shim_classify(pattern):
    # MIRROR: classify_matcher (build-time, build/scripts/generate_hooks.py)
    # and _shim_classify (runtime, this inlined copy) MUST agree on the
    # grammar. Update both when the grammar changes.
    if pattern.startswith("^") and pattern.endswith("$"):
        return "regex", {"pattern": pattern}
    m = _re.match(r"^([A-Za-z_][A-Za-z0-9_]*)\((.*)\)$", pattern)
    if m:
        return "tool-glob", {"toolName": m.group(1), "argsGlob": m.group(2)}
    return "bare", {"toolName": pattern}


def _shim_normalize_args(tool_args):
    r"""Stringify and whitespace-normalize tool_input for fnmatch comparison.

    REQ-003-007: collapse \s+ to a single space and strip ends. Pattern
    is NOT normalized; authors write patterns assuming single spaces.
    """
    if isinstance(tool_args, dict):
        # Bash hooks place command under "command"; keep this fallback
        # path narrow but correct for the live corpus.
        cmd = tool_args.get("command")
        if isinstance(cmd, str):
            text = cmd
        else:
            text = _json.dumps(tool_args, sort_keys=True)
    elif isinstance(tool_args, str):
        text = tool_args
    elif tool_args is None:
        text = ""
    else:
        text = str(tool_args)
    return _re.sub(r"\s+", " ", text).strip()


def _shim_glob_match(args_glob, tool_args_norm):
    """Match each top-level `|` branch as a separate glob alternative."""
    branches = args_glob.split("|") if args_glob else [""]
    for branch in branches:
        if _fnmatch.fnmatchcase(tool_args_norm, branch):
            return True
    return False


def _shim_unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("duplicate JSON object key")
        result[key] = value
    return result


def _shim_load_json(raw_value):
    return _json.loads(raw_value, object_pairs_hook=_shim_unique_object)


def _shim_parse_json_string(raw_value, field_name):
    if isinstance(raw_value, str):
        stripped = raw_value.lstrip()
        if not stripped or stripped[0] not in "{[\"":
            return raw_value
        try:
            return _shim_load_json(raw_value)
        except _json.JSONDecodeError as exc:
            print(
                "matcher-shim [{}]: {} is not valid JSON: {}".format(
                    _MATCHER, field_name, exc
                ),
                file=_sys.stderr,
            )
            return raw_value
    return raw_value


def _shim_tool_input_from_call_args(raw_args):
    return _shim_parse_json_string(raw_args, "toolCalls.args")


def _shim_validate_tool_name(name, field):
    if not isinstance(name, str) or not name.strip():
        raise ValueError("{} must be a non-empty string".format(field))
    if name != name.strip():
        raise ValueError(
            "{} must not have leading or trailing whitespace".format(field)
        )
    return name


def _shim_json_equal(left, right):
    if type(left) is not type(right):
        return False
    if isinstance(left, dict):
        return left.keys() == right.keys() and all(
            _shim_json_equal(left[key], right[key]) for key in left)
    if isinstance(left, list):
        return len(left) == len(right) and all(
            _shim_json_equal(a, b) for a, b in zip(left, right))
    return left == right


def _shim_alias_value(payload, snake, camel, parser=None):
    fields = [field for field in (snake, camel) if field in payload]
    if not fields:
        return False, None, snake, False
    values = [payload[field] for field in fields]
    if parser is not None:
        values = [parser(value, field) for value, field in zip(values, fields)]
    if len(values) == 2 and not _shim_json_equal(values[0], values[1]):
        raise ValueError(
            "conflicting top-level {}/{} values".format(snake, camel)
        )
    changed = fields != [snake] or values[0] != payload[snake]
    return True, values[0], "/".join(fields), changed


def _shim_top_level_candidate(payload):
    has_name, name, _, name_changed = _shim_alias_value(
        payload, "tool_name", "toolName", _shim_validate_tool_name
    )
    if not has_name:
        raise ValueError("hook input missing string `tool_name`/`toolName` field")
    input_payload = payload
    if payload.get("tool_input") is None and "toolArgs" in payload:
        input_payload = {key: value for key, value in payload.items() if key != "tool_input"}
    has_input, tool_input, input_field, input_changed = _shim_alias_value(
        input_payload, "tool_input", "toolArgs", _shim_parse_json_string
    )
    has_call_id, call_id, _, call_id_changed = _shim_alias_value(
        payload, "tool_call_id", "toolCallId"
    )
    if not (name_changed or input_changed or call_id_changed):
        return payload, input_field
    candidate = dict(payload)
    for field in ("toolName", "toolArgs", "toolCallId"):
        candidate.pop(field, None)
    candidate["tool_name"] = name
    if has_input:
        candidate["tool_input"] = tool_input
    if has_call_id:
        candidate["tool_call_id"] = call_id
    return candidate, input_field


def _shim_candidate_payloads(payload):
    if "toolCalls" in payload:
        tool_calls = payload["toolCalls"]
        if not isinstance(tool_calls, list):
            raise ValueError("toolCalls must be a list when present")
        if len(tool_calls) > _MAX_MATCHER_TOOL_CALLS:
            raise ValueError(
                "toolCalls contains {} entries; limit is {}".format(
                    len(tool_calls), _MAX_MATCHER_TOOL_CALLS
                )
            )
        # A payload may carry top-level action fields OR a `toolCalls` batch,
        # never both: the host precedence contract between the two shapes is
        # unverified, so a top-level Read alongside a Bash in `toolCalls` is
        # ambiguous. Reject any mix (empty or non-empty batch) before a guard
        # ever sees a candidate (#3200).
        conflicting = [
            field
            for field in (
                "tool_name",
                "toolName",
                "tool_input",
                "toolArgs",
                "tool_call_id",
                "toolCallId",
            )
            if field in payload
        ]
        if conflicting:
            raise ValueError(
                "toolCalls conflicts with top-level action fields: "
                + ", ".join(conflicting)
            )
        for index, call in enumerate(tool_calls):
            if not isinstance(call, dict):
                raise ValueError(
                    "toolCalls[{}] must be an object".format(index)
                )
            _shim_validate_tool_name(
                call.get("name"), "toolCalls[{}].name".format(index)
            )
        for call in tool_calls:
            name = call["name"]
            candidate = dict(payload)
            for field in (
                "toolCalls",
                "tool_name",
                "toolName",
                "tool_input",
                "toolArgs",
                "tool_call_id",
                "toolCallId",
            ):
                candidate.pop(field, None)
            candidate["tool_name"] = name
            candidate["tool_input"] = _shim_tool_input_from_call_args(call.get("args"))
            if "id" in call:
                candidate["tool_call_id"] = call.get("id")
            yield candidate, "toolCalls.args"
        return
    yield _shim_top_level_candidate(payload)


def _shim_match_candidate(payload, kind, params):
    tool_name = payload.get("tool_name")
    if not isinstance(tool_name, str):
        raise ValueError("hook input missing string `tool_name`/`toolName` field")
    if kind == "regex":
        return _re.fullmatch(params["pattern"], tool_name) is not None
    if kind == "tool-glob":
        if tool_name != params["toolName"]:
            return False
        norm_args = _shim_normalize_args(payload.get("tool_input"))
        return _shim_glob_match(params["argsGlob"], norm_args)
    return tool_name == params["toolName"]


def _shim_select_payloads(payload):
    kind, params = _shim_classify(_MATCHER)
    for candidate, input_field in _shim_candidate_payloads(payload):
        if _shim_match_candidate(candidate, kind, params):
            yield candidate, input_field


def _shim_replay_bytes(payload, selected, raw):
    if selected is payload:
        return raw
    return _json.dumps(selected, separators=(",", ":")).encode("utf-8")


def _shim_exit_code(exc):
    code = exc.code
    if code is None:
        return 0
    if isinstance(code, int):
        return code
    return 1


def _shim_invoke_selection(payload, selection, raw):
    selected, input_field = selection
    replay = _shim_replay_bytes(payload, selected, raw)
    if len(replay) > _MATCHED_SHIM_PAYLOAD_LIMIT_BYTES:
        print(
            (
                "matcher-shim [{}]: matched replay from {} exceeds "
                "{} bytes; refusing"
            ).format(_MATCHER, input_field, _MATCHED_SHIM_PAYLOAD_LIMIT_BYTES),
            file=_sys.stderr,
        )
        return 2
    _sys.stdin = _io.TextIOWrapper(_io.BytesIO(replay), encoding="utf-8")
    try:
        rc = _original_main(replay)
    except SystemExit as exc:
        return _shim_exit_code(exc)
    if rc is None:
        return 0
    return int(rc)


def _shim_dispatch_selections(payload):
    try:
        yield from _shim_select_payloads(payload)
    except Exception as exc:
        print(
            "matcher-shim [{}]: dispatch error: {}".format(_MATCHER, exc),
            file=_sys.stderr,
        )
        _sys.exit(2)


def _shim_debug_trace(fire):
    if not _os.environ.get("COPILOT_HOOK_DEBUG"):
        return
    kind, _ = _shim_classify(_MATCHER)
    _sys.stderr.write(
        "matcher-shim [{}]: kind={} fired={}\n".format(_MATCHER, kind, fire)
    )


def _shim_dispatch():
    try:
        _raw = _sys.stdin.buffer.read(_HOOK_STDIN_CEILING_BYTES + 1)
    except Exception as exc:  # pragma: no cover - defensive
        print(
            "matcher-shim [{}]: failed to buffer stdin: {}".format(_MATCHER, exc),
            file=_sys.stderr,
        )
        _sys.exit(2)
    if len(_raw) > _HOOK_STDIN_CEILING_BYTES:
        print(
            "matcher-shim [{}]: stdin exceeds {} bytes; refusing".format(
                _MATCHER, _HOOK_STDIN_CEILING_BYTES
            ),
            file=_sys.stderr,
        )
        _sys.exit(2)
    try:
        payload = _shim_load_json(_raw or b"{}")
    except ValueError as exc:
        print(
            "matcher-shim [{}]: malformed JSON on stdin: {}".format(_MATCHER, exc),
            file=_sys.stderr,
        )
        _sys.exit(2)
    fire = False
    for selection in _shim_dispatch_selections(payload):
        if not fire:
            fire = True
            _shim_debug_trace(fire)
        rc = _shim_invoke_selection(payload, selection, _raw)
        if rc != 0:
            _sys.exit(rc)
    if not fire:
        _shim_debug_trace(fire)
    _sys.exit(0)
# END MATCHER SHIM

def _original_main(stdin_bytes):
    # original script body begins below
    #!/usr/bin/env python3
    """Block git push when the open PR description does not match the diff.

    Thin adapter over :mod:`push_guard_base`. Activates whenever the push
    changeset is non-empty (glob ``*``) and runs
    ``scripts/validation/pr_description.py`` in CI mode against the active
    PR. Real CRITICAL mismatches (file mentioned but not in diff) block the
    push. Tooling failures (missing gh, no PR open, timeout, OSError) all
    fail-open so a temporary infrastructure problem never wedges the user.

    Hook Type: PreToolUse
    Exit Codes (Claude Hook Semantics, exempt from ADR-035):
        0 = Allow (clean validator, no PR for branch, gh missing, timeout,
            OSError, or empty changeset)
        2 = Block (validator reported CRITICAL mismatches, or config error)
    """


    import shutil
    import subprocess
    import sys

    from _bootstrap import ensure_plugin_paths

    ensure_plugin_paths()

    from push_guard_base import emit_fail_open, run_guard  # noqa: E402
    from hook_utilities import get_project_directory  # noqa: E402

    GUARD_NAME = "pr-description"
    GLOBS = ["*"]
    GH_TIMEOUT = 10
    VALIDATOR_TIMEOUT = 60
    VALIDATOR_PATH = "scripts/validation/pr_description.py"


    def _discover_pr_number(project_dir: str) -> int | None:
        """Return the PR number for the current branch, or None on any failure.

        Uses ``gh pr view`` against the local HEAD. The fail-open semantics are
        intentional: a brand-new branch with no PR open yet, a missing gh
        binary, or a transient gh failure must NOT block the push. The guard
        only exists to catch mismatches once a PR is open and authored.
        """
        if shutil.which("gh") is None:
            print(
                f"[{GUARD_NAME}] gh CLI not on PATH; allowing push (fail-open)",
                file=sys.stderr,
            )
            emit_fail_open(GUARD_NAME, "gh_missing", "gh CLI not on PATH")
            return None
        try:
            proc = subprocess.run(
                ["gh", "pr", "view", "--json", "number", "-q", ".number"],
                capture_output=True,
                text=True,
                timeout=GH_TIMEOUT,
                shell=False,
                check=False,
                cwd=project_dir,
            )
        except subprocess.TimeoutExpired:
            print(
                f"[{GUARD_NAME}] gh pr view timed out after {GH_TIMEOUT}s; "
                f"allowing push (fail-open)",
                file=sys.stderr,
            )
            emit_fail_open(GUARD_NAME, "gh_timeout", f"gh pr view exceeded {GH_TIMEOUT}s")
            return None
        except (FileNotFoundError, OSError) as exc:
            print(
                f"[{GUARD_NAME}] gh pr view failed to invoke: {exc}; "
                f"allowing push (fail-open)",
                file=sys.stderr,
            )
            emit_fail_open(GUARD_NAME, "gh_oserror", f"{type(exc).__name__}: {exc}")
            return None
        if proc.returncode != 0:
            # Distinguish the common failure modes so on-call can act on the
            # real cause: no-PR-yet, auth, network, or generic.
            stderr_text = (proc.stderr or "").strip()
            stderr_lower = stderr_text.lower()
            first_line = stderr_text.splitlines()[0] if stderr_text else "non-zero exit"
            if "no pull requests found" in stderr_lower or "no commits between" in stderr_lower:
                cause = "no PR found for current branch"
                reason = "no_pr_for_branch"
            elif "authent" in stderr_lower or "not logged" in stderr_lower or "token" in stderr_lower:
                cause = "gh auth failure"
                reason = "gh_auth_failure"
            elif "network" in stderr_lower or "could not resolve" in stderr_lower or "timed out" in stderr_lower:
                cause = "gh network failure"
                reason = "gh_network_failure"
            else:
                cause = "gh pr view failed"
                reason = "gh_nonzero_exit"
            print(
                f"[{GUARD_NAME}] {cause} ({first_line}); allowing push (fail-open)",
                file=sys.stderr,
            )
            emit_fail_open(GUARD_NAME, reason, f"{cause}: {first_line}")
            return None
        raw = proc.stdout.strip()
        if not raw:
            print(
                f"[{GUARD_NAME}] gh pr view returned empty PR number; "
                f"allowing push (fail-open)",
                file=sys.stderr,
            )
            emit_fail_open(GUARD_NAME, "gh_empty_output", "gh pr view returned empty PR number")
            return None
        try:
            return int(raw)
        except ValueError:
            print(
                f"[{GUARD_NAME}] gh pr view returned non-numeric PR number "
                f"{raw!r}; allowing push (fail-open)",
                file=sys.stderr,
            )
            emit_fail_open(GUARD_NAME, "gh_nonnumeric_output", f"PR number was {raw!r}")
            return None


    def _parse_critical_lines(stdout: str) -> list[str]:
        """Extract CRITICAL violation blocks from validator stdout.

        Validator format (see scripts/validation/pr_description.py
        print_results):

            [CRITICAL] <issue_type>
              File: <path>
              <message>

        Each block becomes one violation entry that preserves the file path
        and message so the user can act without rerunning the validator.
        """
        violations: list[str] = []
        lines = stdout.splitlines()
        i = 0
        while i < len(lines):
            line = lines[i]
            if line.startswith("[CRITICAL]"):
                block = [line.rstrip()]
                j = i + 1
                while j < len(lines) and (
                    lines[j].startswith("  ") or lines[j].startswith("\t")
                ):
                    stripped = lines[j].rstrip()
                    if stripped:
                        block.append(stripped)
                    j += 1
                violations.append(" ".join(block))
                i = j
                continue
            i += 1
        return violations


    def _validate(_matching: list[str], _all_changed: list[str]) -> list[str]:
        project_dir = get_project_directory()

        pr_num = _discover_pr_number(project_dir)
        if pr_num is None:
            return []

        try:
            proc = subprocess.run(
                [
                    sys.executable,
                    VALIDATOR_PATH,
                    "--pr-number",
                    str(pr_num),
                    "--ci",
                ],
                capture_output=True,
                text=True,
                timeout=VALIDATOR_TIMEOUT,
                shell=False,
                check=False,
                cwd=project_dir,
            )
        except subprocess.TimeoutExpired:
            print(
                f"[{GUARD_NAME}] {VALIDATOR_PATH} timed out after "
                f"{VALIDATOR_TIMEOUT}s; allowing push (fail-open)",
                file=sys.stderr,
            )
            emit_fail_open(
                GUARD_NAME,
                "validator_timeout",
                f"{VALIDATOR_PATH} exceeded {VALIDATOR_TIMEOUT}s",
            )
            return []
        except (FileNotFoundError, OSError) as exc:
            print(
                f"[{GUARD_NAME}] {VALIDATOR_PATH} failed to invoke: {exc}; "
                f"allowing push (fail-open)",
                file=sys.stderr,
            )
            emit_fail_open(
                GUARD_NAME,
                "validator_oserror",
                f"{VALIDATOR_PATH} failed to invoke: {type(exc).__name__}: {exc}",
            )
            return []

        if proc.returncode == 0:
            return []

        if proc.returncode == 2:
            stderr_first = (proc.stderr or "").strip().splitlines()
            reason = stderr_first[0] if stderr_first else "config error"
            return [f"{VALIDATOR_PATH}: config error - {reason}"]

        # rc == 1: CRITICAL mismatch
        violations = _parse_critical_lines(proc.stdout)
        if not violations:
            # Validator returned 1 but stdout did not match the [CRITICAL]
            # parse shape. Surface a generic violation rather than fail-open;
            # the user can rerun the validator locally for full output.
            violations = [
                f"{VALIDATOR_PATH} reported critical issues "
                f"(rc=1, see local run for detail)"
            ]
        violations.append(
            f"Update the PR description to mention only files actually in "
            f"the diff (run {VALIDATOR_PATH} --pr-number {pr_num} for details)."
        )
        return violations


    def main() -> int:
        # include_deletions=True: pr_description.py compares the description
        # against the FULL PR diff (including deletions), so this guard must
        # fire on deletion-only pushes too. The validator never reads the
        # listed paths.
        return run_guard(_validate, GLOBS, GUARD_NAME, include_deletions=True)
    return main()

_shim_dispatch()
